-- Hyprland 配置文件（Lua）
-- 这是一个 Hyprland 窗口管理器的配置文件示例
--
-- 更多信息请参考官方 wiki: https://wiki.hypr.land/

--
-- 请注意，此处并未列出所有可用的设置/选项
-- 完整列表请查看 wiki
--

-- hl.config({ autogenerated = true }) -- 删除此行以移除警告提示

-- 显示器配置 - 详见 https://wiki.hypr.land/Configuring/Basics/Monitors/
-- 格式: monitor=[名称],分辨率@刷新率,位置,缩放
hl.monitor({ output = "", mode = "1920x1080@144", position = "auto", scale = 1.25 }) -- 自动配置显示器，1920x1080分辨率，144Hz刷新率，缩放比例1

-- 工作区配置
-- general.layout = "dwindle"
hl.config({ general = { layout = "scrolling" } })
-- Scrolling 布局：wrap_focus/swapcol = true 表示无限循环（默认）
-- general.wrap_focus = true
-- general.wrap_swapcol = true

-- 更多关键字配置请参考 https://wiki.hypr.land/Configuring/Start/

-- 启动时自动执行你喜欢的应用程序
-- hl.on("hyprland.start", function()
--     hl.exec_cmd("waybar & hyprpaper & firefox") -- 启动状态栏、壁纸和浏览器
-- end)

-- 引入其他配置文件（多文件配置）
-- require("myColors") -- 引入颜色配置

-- 设置常用程序变量
local terminal = "kitty"      -- 终端模拟器
local fileManager = "thunar"  -- 文件管理器
-- local fileManager = "kitty -e lf" -- 文件管理器（在kitty中运行lf）
local menu = "rofi -show drun" -- 应用程序启动器

-- 默认环境变量设置
hl.env("XCURSOR_SIZE", "24")                  -- 鼠标指针大小
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")       -- QT应用主题（如果有qt6ct可以改为qt6ct）

-- 输入法环境变量（fcitx5）
-- hl.env("GTK_IM_MODULE", "fcitx")            -- Wayland 下交给原生输入法前端，避免 fcitx5 诊断通知
hl.env("QT_IM_MODULE", "fcitx")               -- QT 应用使用 fcitx5
hl.env("XMODIFIERS", "@im=fcitx")             -- X11 应用使用 fcitx5
hl.env("SDL_IM_MODULE", "fcitx")              -- SDL 应用使用 fcitx5
hl.env("GLFW_IM_MODULE", "ibus")              -- GLFW 应用（某些游戏）

-- NVIDIA相关环境变量设置
hl.env("LIBVA_DRIVER_NAME", "nvidia")         -- 视频加速驱动
hl.env("XDG_SESSION_TYPE", "wayland")         -- 会话类型为Wayland
hl.env("GBM_BACKEND", "nvidia-drm")           -- 图形缓冲区管理后端
hl.env("__GLX_VENDOR_LIBRARY_NAME", "nvidia") -- GLX供应商库
hl.env("WLR_NO_HARDWARE_CURSORS", "1")        -- 禁用硬件光标
hl.env("QT_WAYLAND_FORCE_DPI", "120")         -- 强制QT应用DPI为120

-- 自启动程序
hl.on("hyprland.start", function()
    hl.exec_cmd([=[waybar -c ~/.config/waybar/Waybar-3.0/config -s ~/.config/waybar/Waybar-3.0/style.css -l top]=]) -- 启动状态栏
    hl.exec_cmd("fcitx5 --replace -d")        -- 启动输入法
    hl.exec_cmd([=[echo 'Xft.dpi:120' | xrdb]=]) -- 设置X资源数据库DPI
    hl.exec_cmd("mako")
    hl.exec_cmd("hyprpolkitagent")
    hl.exec_cmd("blueman-applet & nm-applet")
    hl.exec_cmd("awww-daemon")
    hl.exec_cmd("waypaper --restore")
    hl.exec_cmd("v2rayN")
    hl.exec_cmd("Snipaste")          -- 启动 Snipaste 截图与贴图后台程序
end)

-- 所有配置类别详见 https://wiki.hypr.land/Configuring/Basics/Variables/
hl.config({
    input = {
        kb_layout = "us",      -- 键盘布局为美式英语
        kb_variant = "",       -- 键盘变体
        kb_model = "",         -- 键盘型号
        kb_options = "",       -- 键盘选项
        kb_rules = "",         -- 键盘规则

        follow_mouse = 1,      -- 焦点跟随鼠标：1=是    

        touchpad = {
            natural_scroll = true, -- 自然滚动（类似苹果触控板）：关闭
        },

        sensitivity = 0,       -- 鼠标灵敏度：-1.0到1.0，0表示不修改
    },
})

hl.config({
    general = {
        -- 更多配置选项见 https://wiki.hypr.land/Configuring/Basics/Variables/

        gaps_in = 5,         -- 窗口之间的间隙大小（像素）
        gaps_out = 10,       -- 窗口与屏幕边缘的间隙大小（像素）
        border_size = 2,     -- 窗口边框大小（像素）
        col = {
            active_border = { colors = { "rgba(33ccffee)", "rgba(00ff99ee)" }, angle = 45 }, -- 活动窗口边框颜色（渐变）
            inactive_border = "rgba(595959aa)", -- 非活动窗口边框颜色
        },

        -- 开启撕裂模式前请先阅读 https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/
        allow_tearing = false, -- 是否允许画面撕裂（通常用于游戏等低延迟场景）

        snap = {
            -- 启用窗口捕捉
            enabled = true,
            -- 可选：调整捕捉参数
            window_gap = 5,
            monitor_gap = 10,
            border_overlap = true, --如果开启，两个窗口吸附后，它们之间只保留一个边框的宽度，而不是两个边框的宽度之和。
            respect_gaps = true, --是否考虑系统设置的整体窗口间隙（gaps_in）。
        },
    },
})

hl.config({
    decoration = {
        -- 更多装饰选项见 https://wiki.hypr.land/Configuring/Basics/Variables/

        rounding = 10,          -- 窗口圆角半径（像素）
        active_opacity = 0.99,  -- 活动窗口透明度：0.0-1.0
        inactive_opacity = 0.93, -- 非活动窗口透明度：0.0-1.0
        -- 窗口阴影
        -- 更多阴影选项见 https://wiki.hypr.land/Configuring/Basics/Variables/
        blur = {
            enabled = false, -- 这里可以正常注释
            -- size = 3,     -- 模糊大小
            -- passes = 1,   -- 模糊处理次数（越多越模糊，但性能消耗更大）
            -- xray = true,  -- X射线效果（透过窗口模糊）
            -- vibrancy = 0.1696, -- 模糊活力度（增加透明区域的对比度）
        },

        shadow = {
            -- enabled = true,         -- 启用阴影
            -- range = 10,             -- 阴影范围
            -- render_power = 3,       -- 渲染质量
            -- offset = { 3, 3 },      -- 阴影偏移（X Y）
            -- color = "rgba(1a1a1a66)", -- 半透明黑色阴影
        },

        -- 非活动窗口暗淡效果
        dim_inactive = true,
        dim_strength = 0.025, -- 暗淡强度：2.5%
        dim_special = 0.2,    -- 特殊工作区暗淡强度：20%
    },
})

hl.config({ animations = { enabled = true } }) -- 启用动画效果

-- 默认动画配置，更多信息见 https://wiki.hypr.land/Configuring/Advanced-and-Cool/Animations/

hl.curve("myBezier", { type = "bezier", points = { { 0.05, 0.9 }, { 0.1, 1.05 } } }) -- 自定义贝塞尔曲线（控制动画速度变化）

-- 动画格式：animation = 类型, 速度, 曲线类型, 额外参数
hl.animation({ leaf = "windows", enabled = true, speed = 7, bezier = "myBezier" }) -- 窗口打开动画
hl.animation({ leaf = "windowsOut", enabled = true, speed = 7, bezier = "default", style = "popin 80%" }) -- 窗口关闭动画
hl.animation({ leaf = "border", enabled = true, speed = 10, bezier = "default" }) -- 边框动画
hl.animation({ leaf = "borderangle", enabled = true, speed = 8, bezier = "default" }) -- 边框角度动画
hl.animation({ leaf = "fade", enabled = true, speed = 7, bezier = "default" }) -- 淡入淡出动画
hl.animation({ leaf = "workspaces", enabled = true, speed = 5, bezier = "default" }) -- 工作区切换动画
hl.animation({ leaf = "specialWorkspace", enabled = true, speed = 4, bezier = "myBezier", style = "slidevert" }) -- 特殊工作区：垂直滑动（从上/下）

-- ~/.config/hypr/hyprland.conf 中的分组配置

hl.config({
    group = {
        -- 基础设置
        auto_group = true,                   -- 新窗口自动加入当前分组
        insert_after_current = true,         -- 新窗口插入当前窗口后
        focus_removed_window = true,         -- 移出窗口后自动聚焦
        drag_into_group = 1,                 -- 启用拖拽合并分组
        merge_groups_on_drag = true,         -- 允许分组间拖拽合并

        -- 边框颜色（可自定义）
        col = {
            border_active = 0x66ffff00,        -- 活动分组边框（黄色）
            border_inactive = 0x66777700,      -- 非活动分组边框（暗黄色）
            border_locked_active = 0x66ff6b4d, -- 橙色 - 锁定活跃组
            border_locked_inactive = 0x66555555, -- 中灰色 - 锁定非活跃组
        },

        -- 分组栏美化配置
        groupbar = {
            enabled = true,
            font_family = "JetBrains Mono Nerd Font",
            font_size = 17,
            height = 10,
            gradients = true,
            render_titles = true,
            scrolling = true,

            -- 圆角设计
            rounding = 4,
            rounding_power = 3.0,
            gradient_rounding = 6,
            gradient_rounding_power = 3.0,

            -- 间距调整
            gaps_in = 3,
            gaps_out = 4,
            indicator_height = 2,
            indicator_gap = 2,

            -- 文字颜色
            text_color = "0xffeeeeee",
            text_color_inactive = "0x77ffffff",
            text_color_locked_active = "0xffff6b4d",
            text_color_locked_inactive = "0x77ff6b4d",

            -- 背景渐变颜色
            col = {
                active = 0x3344aaff,          -- 半透明蓝色
                inactive = 0x1a333333,        -- 深色半透明
                locked_active = 0x33ff6b4d,   -- 半透明橙色
                locked_inactive = 0x1a555555, -- 中灰色半透明
            },
        },
    },
})

hl.config({
    dwindle = {
        -- 交错式布局配置，详见 https://wiki.hypr.land/Configuring/Layouts/Dwindle-Layout/
        preserve_split = true, -- 保持分割方向（强烈建议启用）
    },
})

hl.config({
    master = {
        -- See https://wiki.hypr.land/Configuring/Layouts/Master-Layout/ for more
        mfact = 0.5,                  -- 主窗口区域占比（0.0-1.0）
        orientation = "left",         -- 主窗口位置：left, right, top, bottom
        special_scale_factor = 0.8,   -- 特殊工作区的缩放因子
        new_status = "master",        -- 新窗口状态：master, stack
    },
})

hl.config({
    scrolling = {
        -- 滚动布局配置 (Hyprland 0.54+)
        fullscreen_on_one_column = true, -- 单列时全屏显示
        column_width = 0.7,              -- 列默认宽度(50%屏幕宽度)
        direction = "right",             -- 新窗口方向和滚动方向: left/right/down/up
        follow_focus = true,             -- 焦点切换时自动滚动显示窗口
        focus_fit_method = 0,            -- 聚焦时视图调整: 0=居中, 1=适配
        follow_min_visible = 0.4,        -- 焦点窗口至少可见比例
        explicit_column_widths = "0.333,0.5,0.667,0.85,1.0", -- 预配置列宽
        -- wrap_focus = true,            -- ✅ 启用循环聚焦
        -- wrap_swapcol = true,          -- ✅ 启用循环交换
    },
})

