-- 更多关键字配置见 https://wiki.hypr.land/Configuring/Start/
local mainMod = "SUPER" -- 定义主修饰键为Super键（Windows键/Command键）

-- 快捷键绑定示例，更多配置见 https://wiki.hypr.land/Configuring/Basics/Binds/
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd(terminal)) -- Super+Q: 启动终端
hl.bind(mainMod .. " + C", function()
    local window = hl.get_active_window()
    if window and window.class == "ceru-music" then
        hl.exec_cmd("$HOME/.config/hypr/scripts/tray.py ceru") -- Ceru Music: 隐藏到托盘
        return
    end
    if window and window.class == "python3" and window.title == "有道词典" then
        hl.exec_cmd("$HOME/.config/hypr/scripts/tray.py youdao") -- 有道词典: 隐藏到托盘
        return
    end
    hl.exec_cmd("hyprctl dispatch 'hl.dsp.window.close()'") -- 其他窗口：正常关闭
end)
hl.bind(mainMod .. " + M", hl.dsp.exit()) -- Super+M: 退出Hyprland
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager)) -- Super+E: 启动文件管理器
hl.bind(mainMod .. " + Space", hl.dsp.window.float({ action = "toggle" })) -- Super+V: 切换窗口浮动/平铺状态
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(menu)) -- Super+R: 启动应用程序菜单
hl.bind(mainMod .. " + T", hl.dsp.exec_cmd([=[grim -g "$(slurp)" - | wl-copy --type image/png]=])) -- Super+T: 框选截图到剪贴板
hl.bind("F1", hl.dsp.exec_cmd("Snipaste snip -o clipboard")) -- F1: Snipaste 框选并复制到剪贴板
hl.bind("F3", hl.dsp.exec_cmd("Snipaste paste")) -- F3: 将剪贴板图片贴到屏幕
hl.bind("ALT + X", hl.dsp.exec_cmd("$HOME/.config/hypr/scripts/youdao.py")) -- Alt+X: 打开或隐藏有道词典

hl.bind(mainMod .. " + F12", hl.dsp.exec_cmd("pkill -SIGUSR2 waybar"))
hl.bind(mainMod .. " + V", hl.dsp.exec_cmd("pkill -SIGUSR1 waybar")) -- 切换 waybar 显示/隐藏
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.exec_cmd([=[pkill waybar; waybar -c ~/.config/waybar/Waybar-3.0/config -s ~/.config/waybar/Waybar-3.0/style.css -l top &]=])) -- 重新启动 waybar
hl.bind("CTRL + SHIFT + ESCAPE", hl.dsp.exec_cmd("missioncenter")) -- 启动任务中心

-- -------- 布局类型切换 --------
-- 切换到特定布局（带通知）
hl.bind(mainMod .. " + F1", function() hl.config({ general = { layout = "dwindle" } }) end)
hl.bind(mainMod .. " + F2", function() hl.config({ general = { layout = "master" } }) end)
hl.bind(mainMod .. " + F3", function() hl.config({ general = { layout = "scrolling" } }) end)
hl.bind(mainMod .. " + F4", function() hl.config({ general = { layout = "monocle" } }) end)

-- -------- Waybar 快捷键 --------
hl.bind(mainMod .. " + Z", hl.dsp.exec_cmd("$HOME/.config/hypr/scripts/waybar_auto_hide.py")) -- 切换 waybar 显示/隐藏并同步外边距

-- 只在当前布局支持对应消息时执行，避免切换布局后触发运行时错误
local function layout_bind(dispatchers)
    return function()
        local workspace = hl.get_active_workspace()
        local dispatcher = workspace and dispatchers[workspace.tiled_layout]
        if dispatcher then hl.dispatch(dispatcher) end
    end
end

-- -------- Scrolling 布局专用快捷键 --------
-- 左右滚动（移动视图）
hl.bind(mainMod .. " + A", layout_bind({ scrolling = hl.dsp.layout("move -col"), monocle = hl.dsp.layout("cyclenext"), master = hl.dsp.focus({ direction = "left" }), dwindle = hl.dsp.focus({ direction = "left" }) })) -- Super+A: 左（scrolling滚动 / monocle下一个 / master·dwindle焦点左移）
hl.bind(mainMod .. " + D", layout_bind({ scrolling = hl.dsp.layout("move +col"), monocle = hl.dsp.layout("cycleprev"), master = hl.dsp.focus({ direction = "right" }), dwindle = hl.dsp.focus({ direction = "right" }) })) -- Super+D: 右（scrolling滚动 / monocle上一个 / master·dwindle焦点右移）
hl.bind(mainMod .. " + SHIFT + D", layout_bind({ scrolling = hl.dsp.layout("colresize +conf") })) -- Super+Shift+D: 增加列宽（循环预设值）
hl.bind(mainMod .. " + SHIFT + A", layout_bind({ scrolling = hl.dsp.layout("colresize -conf") })) -- Super+Shift+A: 减少列宽（循环预设值）
hl.bind("ALT + mouse_up", layout_bind({ scrolling = hl.dsp.layout("swapcol r") })) -- Alt+ 滚轮下：与右侧列交换
hl.bind("ALT + mouse_down", layout_bind({ scrolling = hl.dsp.layout("swapcol l") })) -- Alt+ 滚轮上：与左侧列交换

-- Monocle 布局：窗口切换（单窗口模式下循环窗口）
-- Super+A / Super+D 已在上方根据当前布局分流
hl.bind("ALT + grave", hl.dsp.window.fullscreen()) -- Alt+`: 切换窗口全屏/恢复

