-- -------- 窗口循环 --------
-- [hidden] Alt+Tab：有浮动窗口时循环浮动窗口，没有浮动窗口时循环平铺窗口
-- 注意：函数内直接调用 hl.dsp.* 在按键回调上下文里不生效（Hyprland 0.56 quirk），
-- 所以切换动作经 hl.exec_cmd + hyprctl dispatch 走已验证可用的路径
hl.bind("ALT + Tab", function()
    local ws = hl.get_active_workspace()
    local floats = 0
    if ws then
        for _, w in ipairs(hl.get_workspace_windows(ws)) do
            if w.floating then floats = floats + 1 end
        end
    end
    if floats > 0 then
        hl.exec_cmd("hyprctl dispatch 'hl.dsp.window.cycle_next({ next = false, floating = true })' && hyprctl dispatch 'hl.dsp.window.bring_to_top()'")
    elseif ws and ws.tiled_layout == "scrolling" then
        hl.exec_cmd("hyprctl dispatch 'hl.dsp.layout(\"focus r\")' && hyprctl dispatch 'hl.dsp.window.bring_to_top()'")
    else
        hl.exec_cmd("hyprctl dispatch 'hl.dsp.window.cycle_next({ next = false, tiled = true })' && hyprctl dispatch 'hl.dsp.window.bring_to_top()'")
    end
end)

